#[test]
fn k3_pretokenize_matches_the_reference_pattern() {
    let mut bad = Vec::new();
    for (input, want) in CASES {
        let got = k3_pretokenize(input);
        if got != *want {
            bad.push(format!("input {input:?}\n     got  {got:?}\n     want {want:?}"));
        }
    }
    assert!(bad.is_empty(), "{} of {} cases differ:\n{}", bad.len(), CASES.len(), bad.join("\n"));
}

/// The pattern's alternatives cover every codepoint, so the pieces must reassemble the
/// input exactly — no character silently dropped by a gap between alternatives.
#[test]
fn k3_pretokenize_is_lossless() {
    for (input, _) in CASES {
        assert_eq!(k3_pretokenize(input).concat(), *input, "lost text on {input:?}");
    }
}

// --- pre-tokenizer selection -----------------------------------------------------
// Hand-written (not generated): these assert which split a tokenizer.json selects, which
// is about detection rather than the pattern itself.

use colibri_json::Json;
use colibri_tokenizer::{PreTok, Tokenizer};

/// A minimal but valid tokenizer.json carrying `pre_tokenizer_json` verbatim.
fn tok_with_pretok(pre: &str) -> Tokenizer {
    let src = format!(
        r#"{{"pre_tokenizer":{pre},
             "model":{{"type":"BPE","vocab":{{"a":0,"b":1}},"merges":[]}}}}"#
    );
    Tokenizer::from_json(&Json::parse(&src).unwrap()).unwrap()
}

/// K3's pattern selects the K3 split.
#[test]
fn k3_pattern_selects_the_k3_split() {
    let pre = r#"{"type":"Sequence","pretokenizers":[
        {"type":"Split","pattern":{"Regex":"[\\p{Han}]+|[^\\r\\n\\p{L}\\p{N}]?[[\\p{Lu}\\p{Lt}\\p{Lm}\\p{Lo}\\p{M}]&&[^\\p{Han}]]*[[\\p{Ll}\\p{Lm}\\p{Lo}\\p{M}]&&[^\\p{Han}]]+"},
         "behavior":"Isolated","invert":false}]}"#;
    assert_eq!(tok_with_pretok(pre).pretok(), PreTok::KimiK3);
}

/// The cl100k pattern — and an absent `pre_tokenizer` — stay on the cl100k split.
#[test]
fn cl100k_and_missing_pretokenizer_stay_cl100k() {
    let cl = r#"{"type":"Split","pattern":{"Regex":"(?i:'s|'t)|[^\\r\\n\\p{L}\\p{N}]?\\p{L}+|\\p{N}{1,3}"},
                 "behavior":"Isolated","invert":false}"#;
    assert_eq!(tok_with_pretok(cl).pretok(), PreTok::Cl100k);
    assert_eq!(tok_with_pretok("null").pretok(), PreTok::Cl100k);
}

/// Naming Han is NOT enough to select K3 — a Qwen-style split does that and must keep
/// cl100k. Only the `&&` class intersection, which is K3-specific, flips it.
#[test]
fn a_han_naming_pattern_alone_does_not_select_k3() {
    let qwen_ish = r#"{"type":"Split","pattern":{"Regex":"[\\p{Han}]+|\\p{L}+|\\p{N}"},
                       "behavior":"Isolated","invert":false}"#;
    assert_eq!(tok_with_pretok(qwen_ish).pretok(), PreTok::Cl100k);
}
